def seed_split(text, cast):
    """씨앗: 글 전체를 해설자 한 사람이 읽는다."""
    return [("해설", text.replace('"', ""))]


def split_script(text, cast):
    """내가 쓰는 함수: 따옴표 밖은 해설, 안은 앞의 해설에 이름이 나온 등장인물이 읽는다. → [(읽는 사람, 글)]"""
    parts = re.split(r'"([^"]*)"', text)                 # [밖, 안, 밖, 안, …]
    out, speaker = [], "해설"
    for i, p in enumerate(parts):
        p = p.strip()
        if not p:
            continue
        if i % 2 == 0:
            out.append(("해설", p))
            for name in cast:
                if name != "해설" and name in p:
                    speaker = name
        else:
            out.append((speaker, p))
    return out


