    rows = []
    for title, text in STORIES.items():
        try:
            got = [(str(a), str(b).strip()) for a, b in fn(text, list(CAST))]
        except Exception as e:
            got = [("오류", type(e).__name__)]
        for sp, tx in STORY_TRUTH[title]:
            mine = next((a for a, b in got if b == tx), None)
            rows.append({"story": title, "text": tx, "want": sp, "got": mine or "(조각 없음)", "ok": mine == sp})
    p = sum(1 for r in rows if r["ok"])
    return {"rows": rows, "passed": p, "score": round_half_up(100 * p / len(rows))}


