def my_fn(x):
    """트랙 F 보기 함수: 일부러 모자라게 만들었다(오전을 모른다)."""
    hours = {"한": 1, "두": 2, "세": 3, "네": 4, "다섯": 5, "여섯": 6, "일곱": 7, "여덟": 8, "아홉": 9, "열": 10}
    m = re.search(r"(한|두|세|네|다섯|여섯|일곱|여덟|아홉|열) 시", x)
    return f"{hours[m.group(1)] + 12:02d}:00" if m else None


def measure(fn, cases):
    """시험을 돌려 통과한 비율을 잰다(오류가 나도 멈추지 않음)."""
    rows = []
    for x, want in cases:
        try:
            got = fn(x)
        except Exception as e:
            got = f"오류: {type(e).__name__}"
        rows.append({"in": x, "want": want, "got": got, "ok": got == want})
    p = sum(1 for r in rows if r["ok"])
    return {"rows": rows, "passed": p, "score": round_half_up(100 * p / max(1, len(rows)))}


