function peerMean(ballots: Ballot[], team: string): number[] | null {
  // 내가 쓰는 함수: team이 받은 점수를 기준별로 평균(소수 둘째 자리). 자기 표는 빼고, 표가 하나도 없으면 null
  const rows = ballots.filter((b) => b.from !== team && team in b.scores).map((b) => b.scores[team]);
  if (rows.length === 0) return null;
  return rows[0].map((_, i) => roundHalfUp(rows.reduce((a, r) => a + r[i], 0) / rows.length, 2));
}

function demoScore(peer: number[], measured: number): number {
  // 데모데이 점수 = 70 × (다섯 평균의 평균 ÷ 5) + 15 × measured. 소수 첫째 자리
  return roundHalfUp(((0.7 * (peer.reduce((a, v) => a + v, 0) / peer.length)) / 5) * 100 + 15 * measured, 1);
}

function levelOf(mine: number | null, target: number | null): number {
  // 측정 단계: 0 숫자 없음 · 1 쟀음 · 2 목표에 닿음
  if (mine === null) return 0;
  return typeof target === "number" && mine >= target ? 2 : 1;
}

function cleanBallot(ballot: Record<string, unknown>, teams: Record<string, unknown>): Record<string, number[]> {
  // 평가표 점검: 발표 순서표에 없는 팀 · 1~5의 정수 다섯 개가 아닌 점수는 뺀다
  const out: Record<string, number[]> = {};
  for (const [team, s] of Object.entries(ballot)) {
    if (!(team in teams)) continue;
    if (!(Array.isArray(s) && s.length === 5 && s.every((v) => Number.isInteger(v) && v >= 1 && v <= 5))) continue;
    out[team] = [...s];
  }
  return out;
}

type TallyRow = { team: string; peer: number[] | null; votes: number; level: number; score: number | null };
function tally(ballots: Ballot[], teams: Record<string, Team>): TallyRow[] {
  // 집계: 팀마다 기준별 평균 · 받은 표 · 점수를 내고 점수 높은 순으로(표가 없는 팀은 맨 뒤)
  const rows: TallyRow[] = Object.entries(teams).map(([name, info]) => {
    const p = peerMean(ballots, name);
    const votes = ballots.filter((b) => b.from !== name && name in b.scores).length;
    return { team: name, peer: p, votes, level: info.level, score: p === null ? null : demoScore(p, info.level) };
  });
  return rows.sort((a, b) => Number(a.score === null) - Number(b.score === null) || -(a.score ?? 0) - -(b.score ?? 0));
}

