const NUM: Record<string, string> = { "0": "zero", "1": "one", "2": "two", "3": "three", "4": "four", "5": "five", "6": "six", "7": "seven", "8": "eight", "9": "nine", "10": "ten", "11": "eleven", "12": "twelve" };

function wordsEn(s: string): string[] {
  // 영어 문장을 견주기 좋은 낱말 리스트로: 소문자 · 문장 부호 제거 · 숫자는 글자로(9 → nine)
  const t = s.toLowerCase().replace(/’/g, "'").replace(/[^a-z0-9' ]/g, " ");
  return t.split(/\s+/).filter(Boolean).map((w) => (Object.hasOwn(NUM, w) ? NUM[w] : w));
}

function seedFeedback(target: string, heard: string): string[] {
  // 씨앗: 띄어쓰기로 나눠 같은 자리의 낱말끼리 견준다(문장 부호 · 대소문자 · 빠진 낱말을 생각하지 않음)
  const t = target.split(/\s+/).filter(Boolean);
  const h = heard.split(/\s+/).filter(Boolean);
  return t.filter((w, i) => i >= h.length || h[i] !== w);
}

function matchedIndices(t: string[], h: string[]): Set<number> {
  // 두 낱말 리스트의 가장 긴 공통 부분(LCS)에 든 t의 번호. difflib 대신 직접 짠 표라 Python · TS가 같은 규칙이다
  const dp: number[][] = Array.from({ length: t.length + 1 }, () => new Array(h.length + 1).fill(0));
  for (let i = t.length - 1; i >= 0; i--) {
    for (let j = h.length - 1; j >= 0; j--) {
      dp[i][j] = t[i] === h[j] ? dp[i + 1][j + 1] + 1 : Math.max(dp[i + 1][j], dp[i][j + 1]);
    }
  }
  const keep = new Set<number>();
  let i = 0;
  let j = 0;
  while (i < t.length && j < h.length) {
    if (t[i] === h[j]) {
      keep.add(i);
      i += 1;
      j += 1;
    } else if (dp[i + 1][j] >= dp[i][j + 1]) {
      i += 1;
    } else {
      j += 1;
    }
  }
  return keep;
}

function wordFeedback(target: string, heard: string): string[] {
  // 내가 쓰는 함수: 목표 문장의 낱말 가운데 받아쓴 글과 짝이 맞지 않은 것만 순서대로
  const t = wordsEn(target);
  const keep = matchedIndices(t, wordsEn(heard));
  return t.filter((_, i) => !keep.has(i));
}

type TutorRow = { id: string; got: string[]; want: string[]; ok: boolean };
function tutorEval(fn: (target: string, heard: string) => string[], items: Tutor[]): { rows: TutorRow[]; passed: number; score: number } {
  // 튜터 평가: 학습자의 말에서 '다시 연습할 낱말'을 정확히 짚었는가
  const rows: TutorRow[] = items.map((it) => {
    let got: string[];
    try {
      got = fn(it.target, it.heard).map((w) => String(w).toLowerCase().replace(/^[.,?!]+|[.,?!]+$/g, ""));
    } catch (e) {
      got = [`오류: ${(e as Error).name}`];
    }
    return { id: it.id, got, want: it.miss, ok: same(got, it.miss) };
  });
  const p = rows.filter((r) => r.ok).length;
  return { rows, passed: p, score: roundHalfUp((100 * p) / rows.length) };
}

function tutorSay(target: string, miss: string[]): string {
  // 튜터의 말(글): 잘한 것과 다시 연습할 낱말
  return miss.length === 0 ? "Great job! That was perfect." : "Good try. Listen again and repeat: " + target;
}

