function myFn(x: string): string | null {
  // 트랙 F 보기 함수: 일부러 모자라게 만들었다(오전을 모른다)
  const hours: Record<string, number> = { 한: 1, 두: 2, 세: 3, 네: 4, 다섯: 5, 여섯: 6, 일곱: 7, 여덟: 8, 아홉: 9, 열: 10 };
  const m = /(한|두|세|네|다섯|여섯|일곱|여덟|아홉|열) 시/.exec(x);
  return m ? `${String(hours[m[1]] + 12).padStart(2, "0")}:00` : null;
}

type FreeRow = { in: string; want: string | null; got: string | null; ok: boolean };
function measure(fn: (x: string) => string | null, cases: [string, string | null][]): { rows: FreeRow[]; passed: number; score: number } {
  // 시험을 돌려 통과한 비율을 잰다(오류가 나도 멈추지 않음)
  const rows: FreeRow[] = cases.map(([x, want]) => {
    let got: string | null;
    try {
      got = fn(x);
    } catch (e) {
      got = `오류: ${(e as Error).name}`;
    }
    return { in: x, want, got, ok: got === want };
  });
  const p = rows.filter((r) => r.ok).length;
  return { rows, passed: p, score: roundHalfUp((100 * p) / Math.max(1, rows.length)) };
}

const seedA = tutorEval(seedFeedback, TUTOR); // 트랙 A: 다시 연습할 낱말을 정확히 짚었나 (8개)
const seedB = bookEval(seedSplit); // 트랙 B: 조각마다 읽는 사람을 맞게 정했나 (14개)
const seedC = interpEval(seedMatch, MEET, 0.0); // 트랙 C: 옳은 문장으로 통역했나 (8개)
const resF = measure(myFn, MY_CASES); // 트랙 F: 팀이 만든 시험으로 잰다
const seeds: Record<string, { passed: number; score: number; rows: unknown[] }> = { A: seedA, B: seedB, C: seedC, F: resF };
for (const [k, r] of Object.entries(seeds)) console.log(`트랙 ${k} · ${TRACKS[k]}: ${r.passed} / ${r.rows.length} → ${r.score.toFixed(1)}점`);
console.log("[A] 씨앗이 틀린 문장:", seedA.rows.filter((r) => !r.ok).map((r) => r.id).join(" · "));
console.log("[C] 씨앗이 통역한 문장:", seedC.rows.filter((r) => r.got !== null).map((r) => r.id), "· 통역하지 않아서 맞은 것:", seedC.rows.filter((r) => r.ok).map((r) => r.id));
console.log("[F] 보기 함수가 틀린 시험:", resF.rows.filter((r) => !r.ok).map((r) => r.in));

const ok =
  same(Object.keys(TRACKS), ["A", "B", "C", "F"]) && TUTOR.length === 8 && MEET.length === 8 && seedB.rows.length === 14 &&
  same([seedA.passed, seedA.score], [4, 50]) && same(seedA.rows.filter((r) => !r.ok).map((r) => r.id), ["A1", "A3", "A6", "A8"]) &&
  same([seedB.passed, seedB.score], [0, 0]) &&
  same([seedC.passed, seedC.score, seedC.wrong], [2, 25, 0]) && same(seedC.rows.filter((r) => r.ok).map((r) => r.id), ["C7", "C8"]) &&
  same([resF.passed, resF.score], [2, 66.7]) && same(resF.rows.map((r) => r.ok), [true, false, true]);
check(ok, "씨앗 세 가지는 50 · 0 · 25점에서 출발하고(씨앗 C는 통역하지 않아서 맞은 것 둘뿐), 자유 주제의 보기 함수는 오전을 몰라 3개 가운데 1개를 틀려야 해요.");

