# D51 · 3시간에 들어가는 만큼 — 단독 실행 완성 코드 (Python 3.11)
# pip install (설치 불필요 · 표준 라이브러리만)
# 실행: python d51_scope.py   (인터넷 · GPU · 마이크 불필요 · 받아쓰기 · 말하기 모델은 쓰지 않고, 받아쓴 글을 미리 적어 둔 값으로 흉내)
#   must를 먼저 넣고 가치 높은 순으로 남은 시간에 채운다 · 한 장 기획서의 빈 곳을 찾는다
import math, re


def check(cond: bool, hint: str = "정답을 다시 확인하세요.") -> None:
    """정답 확인 도우미: 조건이 맞으면 정답, 아니면 힌트를 보여 준다."""
    print("[정답] 정답입니다!" if cond else f"[다시] {hint}")


def round_half_up(x, nd=1):
    """반올림 규칙을 하나로: .5는 0에서 먼 쪽으로. (파이썬 round는 짝수 쪽 · JS Math.round는 위쪽이라 둘이 달라서 Python · TS 모두 이 함수를 쓴다)"""
    f = 10 ** nd
    return math.copysign(math.floor(abs(x) * f + 0.5) / f, x)


def clean(s):
    """글자 · 숫자만 남긴다(공백 · 문장 부호 제거)."""
    return re.sub(r"[^0-9A-Za-z가-힣]", "", s)


TRACKS = {'A': '외국어 회화 튜터', 'B': '오디오북 생성기 확장', 'C': '회의 통역기', 'F': '자유 주제'}


FEATURES = [
    {'name': '받아쓰기', 'min': 30, 'must': True, 'value': 5},
    {'name': '예쁜 화면', 'min': 60, 'must': False, 'value': 3},
    {'name': '피드백 음성', 'min': 20, 'must': False, 'value': 4},
    {'name': '점수 재기', 'min': 25, 'must': True, 'value': 5},
    {'name': '다국어', 'min': 90, 'must': False, 'value': 4},
    {'name': '말속도 조절', 'min': 10, 'must': False, 'value': 2},
]
PLAN = {'team': '우리 팀', 'track': 'A', 'title': '', 'user': '', 'problem': '', 'features': [{'name': '핵심 함수 고치기', 'min': 30, 'must': True, 'value': 5}, {'name': '점수 재기', 'min': 15, 'must': True, 'value': 5}, {'name': '결과를 소리로 들려주기', 'min': 20, 'must': False, 'value': 4}, {'name': '예쁜 화면', 'min': 60, 'must': False, 'value': 2}], 'metric': {'name': '씨앗 시험의 점수', 'target': 85}}                                            # 한 장 기획서(아직 비어 있는 곳이 있음)


def pick_scope(features, minutes):
    """내가 쓰는 함수: must는 모두 넣고, 나머지는 가치 높은 순(같으면 짧은 순)으로 남은 시간에 들어가는 것만 넣는다."""
    out, left = [], minutes
    for f in features:
        if f["must"]:
            out.append(f["name"])
            left -= f["min"]
    for f in sorted([f for f in features if not f["must"]], key=lambda f: (-f["value"], f["min"])):
        if f["min"] <= left:
            out.append(f["name"])
            left -= f["min"]
    return out


def check_plan(plan):
    """기획서에서 빠졌거나 모호한 곳을 찾는다. → 고칠 곳의 리스트(비어 있으면 통과)"""
    bad = []
    if not plan.get("team") or plan["team"] == "우리 팀":
        bad.append("team: 팀 이름을 정하세요")
    if plan.get("track") not in TRACKS:
        bad.append("track: A · B · C · F 가운데 하나")
    user = str(plan.get("user") or "")
    if len(user) < 4 or "모든" in user or "누구나" in user:
        bad.append("user: 누가 쓰나요? '모든 사람'이 아니라 한 사람을 떠올릴 수 있게")
    if len(str(plan.get("problem") or "")) < 12:
        bad.append("problem: 그 사람이 지금 무엇이 불편한가요? 한 문장으로(12자 이상)")
    f = plan.get("features") or []
    if not (len(f) >= 3 and all({"name", "min", "must", "value"} <= set(x) for x in f)):
        bad.append("features: 기능 3개 이상, 기능마다 name · min · must · value")
    elif not any(x["must"] for x in f):
        bad.append("features: 꼭 있어야 하는 기능(must=True)이 하나는 있어야 합니다")
    m = plan.get("metric") or {}
    if not (len(str(m.get("name") or "")) >= 4 and isinstance(m.get("target"), (int, float))):
        bad.append("metric: '됐다'를 보여 줄 숫자의 이름(name)과 목표값(target)")
    return bad


cases = [(FEATURES, 120, ["받아쓰기", "점수 재기", "피드백 음성", "말속도 조절"]),      # must 55분 → 남은 65분에 피드백(20) · 말속도(10)만 들어감
         (FEATURES, 60, ["받아쓰기", "점수 재기"]),                                  # must만으로 55분 → 남은 5분에는 아무것도 못 넣음
         (FEATURES, 240, ["받아쓰기", "점수 재기", "피드백 음성", "다국어", "예쁜 화면", "말속도 조절"]),
         (FEATURES[1:3], 15, [])]                                                    # must가 없고 15분에 들어가는 기능도 없음
got = [pick_scope(f, m) for f, m, _ in cases]
for (f, m, want), g in zip(cases, got):
    print(f"{m:>3}분 → {' → '.join(g) or '(없음)'}")
ok_scope = len(got) == 4 and got == [w for _, _, w in cases]

todo = check_plan(PLAN)                                  # 아직 비어 있는 기획서
print(f"기획서 점검: 고칠 곳 {len(todo)}개")
for t in todo:
    print("   ·", t)
filled = {**PLAN, "team": "메아리", "title": "따라 말하기 튜터", "user": "영어 면접을 준비하는 취업 준비생", "problem": "내 발음에서 어느 낱말이 틀렸는지 몰라 같은 실수를 되풀이한다"}
todo2 = check_plan(filled)
no_must = {**filled, "features": [{**f, "must": False} for f in PLAN["features"]]}
print("채운 기획서 점검:", todo2 or "빠진 곳이 없습니다", "· must를 모두 뺀 기획서:", check_plan(no_must))
plan_scope = pick_scope(PLAN["features"], 80)            # 오늘 쓸 수 있는 시간 80분
print("80분에 들어가는 기능:", " → ".join(plan_scope))
ok_plan = (len(todo) == 3 and [t.split(":")[0] for t in todo] == ["team", "user", "problem"] and todo2 == []
           and [t.split(":")[0] for t in check_plan(no_must)] == ["features"]
           and plan_scope == ["핵심 함수 고치기", "점수 재기", "결과를 소리로 들려주기"])

check(ok_scope and ok_plan, "must를 먼저 빼고 남은 시간에 가치 높은 순으로 채워야 하고, 기획서 점검은 빈 곳(team · user · problem)과 must 없음을 찾아야 해요.")

