// D51 · 3시간에 들어가는 만큼 — 단독 실행 완성 코드 (Node 26 · TypeScript)
// 설치 불필요 (Node 내장만)
// 실행: node --experimental-strip-types d51_scope.ts   (인터넷 · GPU · 마이크 불필요 · 받아쓰기 · 말하기 모델은 쓰지 않고, 받아쓴 글을 미리 적어 둔 값으로 흉내)
//   must를 먼저 넣고 가치 높은 순으로 남은 시간에 채운다 · 한 장 기획서의 빈 곳을 찾는다
function check(cond: boolean, hint: string = "정답을 다시 확인하세요."): void {
  // 정답 확인 도우미: 조건이 맞으면 정답, 아니면 힌트를 보여 준다
  console.log(cond ? "[정답] 정답입니다!" : `[다시] ${hint}`);
}

function roundHalfUp(x: number, nd: number = 1): number {
  // 반올림 규칙을 하나로: .5는 0에서 먼 쪽으로. (파이썬 round는 짝수 쪽 · JS Math.round는 위쪽이라 둘이 달라서 Python · TS 모두 이 함수를 쓴다)
  const f = 10 ** nd;
  return Math.sign(x) * (Math.floor(Math.abs(x) * f + 0.5) / f);
}

const same = (a: unknown, b: unknown): boolean => JSON.stringify(a) === JSON.stringify(b); // 값 전체가 같은지 (모양과 순서까지)
const clean = (s: string): string => s.replace(/[^0-9A-Za-z가-힣]/g, ""); // 글자 · 숫자만 남긴다(공백 · 문장 부호 제거)

const TRACKS: Record<string, string> = {"A": "외국어 회화 튜터", "B": "오디오북 생성기 확장", "C": "회의 통역기", "F": "자유 주제"};

type Feature = { name: string; min: number; must: boolean; value: number };
const FEATURES: Feature[] = [
  {"name": "받아쓰기", "min": 30, "must": true, "value": 5},
  {"name": "예쁜 화면", "min": 60, "must": false, "value": 3},
  {"name": "피드백 음성", "min": 20, "must": false, "value": 4},
  {"name": "점수 재기", "min": 25, "must": true, "value": 5},
  {"name": "다국어", "min": 90, "must": false, "value": 4},
  {"name": "말속도 조절", "min": 10, "must": false, "value": 2},
];
const PLAN: Record<string, any> = {"team": "우리 팀", "track": "A", "title": "", "user": "", "problem": "", "features": [{"name": "핵심 함수 고치기", "min": 30, "must": true, "value": 5}, {"name": "점수 재기", "min": 15, "must": true, "value": 5}, {"name": "결과를 소리로 들려주기", "min": 20, "must": false, "value": 4}, {"name": "예쁜 화면", "min": 60, "must": false, "value": 2}], "metric": {"name": "씨앗 시험의 점수", "target": 85}}; // 한 장 기획서(아직 비어 있는 곳이 있음)

function pickScope(features: Feature[], minutes: number): string[] {
  // 내가 쓰는 함수: must는 모두 넣고, 나머지는 가치 높은 순(같으면 짧은 순)으로 남은 시간에 들어가는 것만 넣는다
  const out: string[] = [];
  let left = minutes;
  for (const f of features) {
    if (f.must) {
      out.push(f.name);
      left -= f.min;
    }
  }
  for (const f of features.filter((x) => !x.must).sort((a, b) => b.value - a.value || a.min - b.min)) {
    if (f.min <= left) {
      out.push(f.name);
      left -= f.min;
    }
  }
  return out;
}

function checkPlan(plan: Record<string, any>): string[] {
  // 기획서에서 빠졌거나 모호한 곳을 찾는다. → 고칠 곳의 리스트(비어 있으면 통과)
  const bad: string[] = [];
  if (!plan.team || plan.team === "우리 팀") bad.push("team: 팀 이름을 정하세요");
  if (!Object.hasOwn(TRACKS, plan.track)) bad.push("track: A · B · C · F 가운데 하나");
  const user = String(plan.user || "");
  if (user.length < 4 || user.includes("모든") || user.includes("누구나")) bad.push("user: 누가 쓰나요? '모든 사람'이 아니라 한 사람을 떠올릴 수 있게");
  if (String(plan.problem || "").length < 12) bad.push("problem: 그 사람이 지금 무엇이 불편한가요? 한 문장으로(12자 이상)");
  const f: Feature[] = plan.features || [];
  if (!(f.length >= 3 && f.every((x) => ["name", "min", "must", "value"].every((k) => k in x)))) bad.push("features: 기능 3개 이상, 기능마다 name · min · must · value");
  else if (!f.some((x) => x.must)) bad.push("features: 꼭 있어야 하는 기능(must=True)이 하나는 있어야 합니다");
  const m = plan.metric || {};
  if (!(String(m.name || "").length >= 4 && typeof m.target === "number")) bad.push("metric: '됐다'를 보여 줄 숫자의 이름(name)과 목표값(target)");
  return bad;
}

const cases: [Feature[], number, string[]][] = [
  [FEATURES, 120, ["받아쓰기", "점수 재기", "피드백 음성", "말속도 조절"]], // must 55분 → 남은 65분에 피드백(20) · 말속도(10)만 들어감
  [FEATURES, 60, ["받아쓰기", "점수 재기"]], // must만으로 55분 → 남은 5분에는 아무것도 못 넣음
  [FEATURES, 240, ["받아쓰기", "점수 재기", "피드백 음성", "다국어", "예쁜 화면", "말속도 조절"]],
  [FEATURES.slice(1, 3), 15, []], // must가 없고 15분에 들어가는 기능도 없음
];
const got = cases.map(([f, m]) => pickScope(f, m));
cases.forEach(([, m], i) => console.log(`${String(m).padStart(3)}분 → ${got[i].join(" → ") || "(없음)"}`));
const okScope = got.length === 4 && same(got, cases.map((c) => c[2]));

const todo = checkPlan(PLAN); // 아직 비어 있는 기획서
console.log(`기획서 점검: 고칠 곳 ${todo.length}개`);
for (const t of todo) console.log("   ·", t);
const filled = { ...PLAN, team: "메아리", title: "따라 말하기 튜터", user: "영어 면접을 준비하는 취업 준비생", problem: "내 발음에서 어느 낱말이 틀렸는지 몰라 같은 실수를 되풀이한다" };
const todo2 = checkPlan(filled);
const noMust = { ...filled, features: PLAN.features.map((f: Feature) => ({ ...f, must: false })) };
console.log("채운 기획서 점검:", todo2.length ? todo2 : "빠진 곳이 없습니다", "· must를 모두 뺀 기획서:", checkPlan(noMust));
const planScope = pickScope(PLAN.features, 80); // 오늘 쓸 수 있는 시간 80분
console.log("80분에 들어가는 기능:", planScope.join(" → "));
const okPlan =
  todo.length === 3 && same(todo.map((t) => t.split(":")[0]), ["team", "user", "problem"]) && todo2.length === 0 &&
  same(checkPlan(noMust).map((t) => t.split(":")[0]), ["features"]) && same(planScope, ["핵심 함수 고치기", "점수 재기", "결과를 소리로 들려주기"]);

check(okScope && okPlan, "must를 먼저 빼고 남은 시간에 가치 높은 순으로 채워야 하고, 기획서 점검은 빈 곳(team · user · problem)과 must 없음을 찾아야 해요.");

