const same = (a: unknown, b: unknown): boolean => JSON.stringify(a) === JSON.stringify(b); // 값 전체가 같은지 (모양과 순서까지)
const clean = (s: string): string => s.replace(/[^0-9A-Za-z가-힣]/g, ""); // 글자 · 숫자만 남긴다(공백 · 문장 부호 제거)

const TRACKS: Record<string, string> = {"A": "외국어 회화 튜터", "B": "오디오북 생성기 확장", "C": "회의 통역기", "F": "자유 주제"};

type Tutor = { id: string; target: string; heard: string; miss: string[] };
const TUTOR: Tutor[] = [
  {"id": "A1", "target": "I would like a cup of coffee, please.", "heard": "i would like a cup of coffee please", "miss": []},
  {"id": "A2", "target": "Could you tell me how to get to the station?", "heard": "Could you tell me how to go to the station?", "miss": ["get"]},
  {"id": "A3", "target": "I have lived in Seoul for three years.", "heard": "I lived in Seoul for three years.", "miss": ["have"]},
  {"id": "A4", "target": "She doesn't like spicy food.", "heard": "She don't like spicy food.", "miss": ["doesn't"]},
  {"id": "A5", "target": "Where is the nearest subway station?", "heard": "Where is the nearest subway station?", "miss": []},
  {"id": "A6", "target": "I am looking for a bigger size.", "heard": "I am looking a bigger size.", "miss": ["for"]},
  {"id": "A7", "target": "Can I pay by credit card?", "heard": "Can I pay with credit card?", "miss": ["by"]},
  {"id": "A8", "target": "The meeting starts at nine tomorrow.", "heard": "The meeting starts at 9 tomorrow.", "miss": []},
]; // 학습자의 말 8개: 목표 문장 · 받아쓴 글(받아쓰기 모델 대신 미리 적어 둔 값) · 짚어야 할 낱말
const NUM: Record<string, string> = { "0": "zero", "1": "one", "2": "two", "3": "three", "4": "four", "5": "five", "6": "six", "7": "seven", "8": "eight", "9": "nine", "10": "ten", "11": "eleven", "12": "twelve" };

function wordsEn(s: string): string[] {
  // 영어 문장을 견주기 좋은 낱말 리스트로: 소문자 · 문장 부호 제거 · 숫자는 글자로(9 → nine)
  const t = s.toLowerCase().replace(/’/g, "'").replace(/[^a-z0-9' ]/g, " ");
  return t.split(/\s+/).filter(Boolean).map((w) => (Object.hasOwn(NUM, w) ? NUM[w] : w));
}

function seedFeedback(target: string, heard: string): string[] {
  // 씨앗: 띄어쓰기로 나눠 같은 자리의 낱말끼리 견준다(문장 부호 · 대소문자 · 빠진 낱말을 생각하지 않음)
  const t = target.split(/\s+/).filter(Boolean);
  const h = heard.split(/\s+/).filter(Boolean);
  return t.filter((w, i) => i >= h.length || h[i] !== w);
}

function matchedIndices(t: string[], h: string[]): Set<number> {
  // 두 낱말 리스트의 가장 긴 공통 부분(LCS)에 든 t의 번호. difflib 대신 직접 짠 표라 Python · TS가 같은 규칙이다
  const dp: number[][] = Array.from({ length: t.length + 1 }, () => new Array(h.length + 1).fill(0));
  for (let i = t.length - 1; i >= 0; i--) {
    for (let j = h.length - 1; j >= 0; j--) {
      dp[i][j] = t[i] === h[j] ? dp[i + 1][j + 1] + 1 : Math.max(dp[i + 1][j], dp[i][j + 1]);
    }
  }
  const keep = new Set<number>();
  let i = 0;
  let j = 0;
  while (i < t.length && j < h.length) {
    if (t[i] === h[j]) {
      keep.add(i);
      i += 1;
      j += 1;
    } else if (dp[i + 1][j] >= dp[i][j + 1]) {
      i += 1;
    } else {
      j += 1;
    }
  }
  return keep;
}

function wordFeedback(target: string, heard: string): string[] {
  // 내가 쓰는 함수: 목표 문장의 낱말 가운데 받아쓴 글과 짝이 맞지 않은 것만 순서대로
  const t = wordsEn(target);
  const keep = matchedIndices(t, wordsEn(heard));
  return t.filter((_, i) => !keep.has(i));
}

type TutorRow = { id: string; got: string[]; want: string[]; ok: boolean };
function tutorEval(fn: (target: string, heard: string) => string[], items: Tutor[]): { rows: TutorRow[]; passed: number; score: number } {
  // 튜터 평가: 학습자의 말에서 '다시 연습할 낱말'을 정확히 짚었는가
  const rows: TutorRow[] = items.map((it) => {
    let got: string[];
    try {
      got = fn(it.target, it.heard).map((w) => String(w).toLowerCase().replace(/^[.,?!]+|[.,?!]+$/g, ""));
    } catch (e) {
      got = [`오류: ${(e as Error).name}`];
    }
    return { id: it.id, got, want: it.miss, ok: same(got, it.miss) };
  });
  const p = rows.filter((r) => r.ok).length;
  return { rows, passed: p, score: roundHalfUp((100 * p) / rows.length) };
}

function tutorSay(target: string, miss: string[]): string {
  // 튜터의 말(글): 잘한 것과 다시 연습할 낱말
  return miss.length === 0 ? "Great job! That was perfect." : "Good try. Listen again and repeat: " + target;
}

const seed = tutorEval(seedFeedback, TUTOR);
const mine = tutorEval(wordFeedback, TUTOR);
console.log(`씨앗 ${seed.passed} / ${TUTOR.length} → ${seed.score.toFixed(1)}점 · 내 함수 ${mine.passed} / ${TUTOR.length} → ${mine.score.toFixed(1)}점`);
for (const r of mine.rows) console.log(`  ${r.id} 짚은 낱말: ${r.got.join(" · ") || "(없음)"} · 정답: ${r.want.join(" · ") || "(없음)"} ${r.ok ? "ok" : "X"}`);

const cases: [[string, string], string[]][] = [
  [["I would like a cup of coffee, please.", "I would like a cup of coffee please."], []], // 쉼표 · 마침표는 무시
  [["I have lived in Seoul for three years.", "I lived in Seoul for three years."], ["have"]], // 낱말 하나가 빠져도 뒤쪽이 밀리지 않음
  [["Can I pay by credit card?", "Can I pay with credit card?"], ["by"]],
  [["The meeting starts at nine tomorrow.", "The meeting starts at 9 tomorrow."], []], // 숫자는 글자로 바꿔 견줌
  [["Where is the station?", ""], ["where", "is", "the", "station"]], // 아무것도 못 들었으면 전부
];
const got = cases.map(([[t, h]]) => wordFeedback(t, h));
const okCases = got.length === 5 && same(got, cases.map((c) => c[1]));

const x = TUTOR[2];
const miss = wordFeedback(x.target, x.heard);
const say = tutorSay(x.target, miss);
console.log("튜터의 말:", say, "· 다시 연습할 낱말:", miss);
const okSay = same(miss, ["have"]) && say.startsWith("Good try") && tutorSay("Hello.", []).startsWith("Great job");

const ok =
  seed.passed === 4 && seed.score === 50 && same(seed.rows.filter((r) => !r.ok).map((r) => r.id), ["A1", "A3", "A6", "A8"]) &&
  mine.passed === 8 && mine.score === 100 && same(mine.rows.map((r) => r.got), TUTOR.map((r) => r.miss));
check(ok && okCases && okSay, "씨앗은 4/8(50점)이고 낱말 맞추기는 8/8이어야 해요. 낱말이 하나 빠져도 뒤쪽이 밀리지 않고, 쉼표 · 대소문자 · 숫자 표기는 같게 봐야 해요.");

book.python:
# D51 · 오디오북: 누가 읽을까 — 단독 실행 완성 코드 (Python 3.11)
# pip install (설치 불필요 · 표준 라이브러리만)
# 실행: python d51_book.py   (인터넷 · GPU · 마이크 불필요 · 받아쓰기 · 말하기 모델은 쓰지 않고, 받아쓴 글을 미리 적어 둔 값으로 흉내)
#   따옴표 밖은 해설, 안은 앞 문장에 이름이 나온 등장인물이 읽도록 조각을 나눈다
import math, re


def check(cond: bool, hint: str = "정답을 다시 확인하세요.") -> None:
    """정답 확인 도우미: 조건이 맞으면 정답, 아니면 힌트를 보여 준다."""
    print("[정답] 정답입니다!" if cond else f"[다시] {hint}")


def round_half_up(x, nd=1):
    """반올림 규칙을 하나로: .5는 0에서 먼 쪽으로. (파이썬 round는 짝수 쪽 · JS Math.round는 위쪽이라 둘이 달라서 Python · TS 모두 이 함수를 쓴다)"""
    f = 10 ** nd
    return math.copysign(math.floor(abs(x) * f + 0.5) / f, x)


def clean(s):
    """글자 · 숫자만 남긴다(공백 · 문장 부호 제거)."""
    return re.sub(r"[^0-9A-Za-z가-힣]", "", s)


TRACKS = {'A': '외국어 회화 튜터', 'B': '오디오북 생성기 확장', 'C': '회의 통역기', 'F': '자유 주제'}


CAST = {'해설': 7, '토끼': 2, '거북이': 5, '다람쥐': 0, '부엉이': 8}                                           # 등장인물 → 목소리 번호
STORIES = {
    '저녁 숲': '숲속 마을에 저녁이 찾아왔습니다. 토끼가 하늘을 보며 말했습니다. "벌써 해가 지네. 이제 집에 가야 해." 거북이가 천천히 고개를 들었습니다. "서두르지 마. 천천히 가도 늦지 않아." 토끼는 발을 동동 굴렀습니다. "너는 느려서 그렇지!" 그러자 거북이가 웃으며 대답했습니다. "느려도 길은 잃지 않아." 둘은 나란히 집으로 걸어갔습니다.',
    '한밤의 손님': '"누구 없어요?" 다람쥐가 문을 두드렸습니다. 한참 뒤에 부엉이가 창문을 열었습니다. "이 밤중에 무슨 일이니?" 다람쥐는 작은 자루를 내밀었습니다. "도토리를 나눠 드리려고요."',
}
STORY_TRUTH = {
    '저녁 숲': [('해설', '숲속 마을에 저녁이 찾아왔습니다. 토끼가 하늘을 보며 말했습니다.'), ('토끼', '벌써 해가 지네. 이제 집에 가야 해.'), ('해설', '거북이가 천천히 고개를 들었습니다.'), ('거북이', '서두르지 마. 천천히 가도 늦지 않아.'), ('해설', '토끼는 발을 동동 굴렀습니다.'), ('토끼', '너는 느려서 그렇지!'), ('해설', '그러자 거북이가 웃으며 대답했습니다.'), ('거북이', '느려도 길은 잃지 않아.'), ('해설', '둘은 나란히 집으로 걸어갔습니다.')],
    '한밤의 손님': [('다람쥐', '누구 없어요?'), ('해설', '다람쥐가 문을 두드렸습니다. 한참 뒤에 부엉이가 창문을 열었습니다.'), ('부엉이', '이 밤중에 무슨 일이니?'), ('해설', '다람쥐는 작은 자루를 내밀었습니다.'), ('다람쥐', '도토리를 나눠 드리려고요.')],
}                              # 정답: (읽는 사람, 글) 조각


def seed_split(text, cast):
    """씨앗: 글 전체를 해설자 한 사람이 읽는다."""
    return [("해설", text.replace('"', ""))]


def split_script(text, cast):
    """내가 쓰는 함수: 따옴표 밖은 해설, 안은 앞의 해설에 이름이 나온 등장인물이 읽는다. → [(읽는 사람, 글)]"""
    parts = re.split(r'"([^"]*)"', text)                 # [밖, 안, 밖, 안, …]
    out, speaker = [], "해설"
    for i, p in enumerate(parts):
        p = p.strip()
        if not p:
            continue
        if i % 2 == 0:
            out.append(("해설", p))
            for name in cast:
                if name != "해설" and name in p:
                    speaker = name
        else:
            out.append((speaker, p))
    return out


def book_eval(fn):
    """오디오북 평가: 두 이야기의 조각 14개를 (읽는 사람, 글)까지 정확히 나눴는가. → {rows, passed, score}"""
    rows = []
    for title, text in STORIES.items():
        try:
            got = [(str(a), str(b).strip()) for a, b in fn(text, list(CAST))]
        except Exception as e:
            got = [("오류", type(e).__name__)]
        for sp, tx in STORY_TRUTH[title]:
            mine = next((a for a, b in got if b == tx), None)
            rows.append({"story": title, "text": tx, "want": sp, "got": mine or "(조각 없음)", "ok": mine == sp})
    p = sum(1 for r in rows if r["ok"])
    return {"rows": rows, "passed": p, "score": round_half_up(100 * p / len(rows))}


seed = book_eval(seed_split)
mine = book_eval(split_script)
print(f"씨앗 {seed['passed']} / {len(seed['rows'])} → {seed['score']}점 · 내 함수 {mine['passed']} / {len(mine['rows'])} → {mine['score']}점")
for who, line in split_script(STORIES["한밤의 손님"], list(CAST)):
    print(f"   [{who}] {line}")
wrong = [r for r in mine["rows"] if not r["ok"]]
for r in wrong:
    print(f"   아직 틀림: {r['text']} → 읽는 사람 {r['got']} (정답 {r['want']})")

cast = ["해설", "토끼", "거북이"]
cases = [('토끼가 말했습니다. "가자." 거북이가 웃었습니다. "그래." 둘은 걸었습니다.', [("해설", "토끼가 말했습니다."), ("토끼", "가자."), ("해설", "거북이가 웃었습니다."), ("거북이", "그래."), ("해설", "둘은 걸었습니다.")]),
         ("바람이 불었습니다.", [("해설", "바람이 불었습니다.")]),                                                                              # 따옴표가 없으면 해설 한 조각
         ('"어서 와." 토끼가 손을 흔들었습니다. "보고 싶었어."', [("해설", "어서 와."), ("해설", "토끼가 손을 흔들었습니다."), ("토끼", "보고 싶었어.")])]   # 앞에 이름이 없으면 해설
got = [split_script(t, cast) for t, _ in cases]
ok_cases = len(got) == 3 and got == [w for _, w in cases]

ok = (seed["passed"] == 0 and seed["score"] == 0.0 and len(STORY_TRUTH["저녁 숲"]) + len(STORY_TRUTH["한밤의 손님"]) == 14
      and mine["passed"] == 13 and mine["score"] == 92.9 and len(wrong) == 1 and wrong[0]["text"] == "누구 없어요?" and wrong[0]["got"] == "해설" and wrong[0]["want"] == "다람쥐")
check(ok and ok_cases, "씨앗은 14조각 가운데 0개, 내 함수는 13개(92.9점)여야 해요. 맨 앞 따옴표처럼 앞에 이름이 없는 대사는 해설로 읽혀 한 조각이 아직 틀립니다.")

book.typescript:
// D51 · 오디오북: 누가 읽을까 — 단독 실행 완성 코드 (Node 26 · TypeScript)
// 설치 불필요 (Node 내장만)
// 실행: node --experimental-strip-types d51_book.ts   (인터넷 · GPU · 마이크 불필요 · 받아쓰기 · 말하기 모델은 쓰지 않고, 받아쓴 글을 미리 적어 둔 값으로 흉내)
//   따옴표 밖은 해설, 안은 앞 문장에 이름이 나온 등장인물이 읽도록 조각을 나눈다
function check(cond: boolean, hint: string = "정답을 다시 확인하세요."): void {
  // 정답 확인 도우미: 조건이 맞으면 정답, 아니면 힌트를 보여 준다
  console.log(cond ? "[정답] 정답입니다!" : `[다시] ${hint}`);
}

function roundHalfUp(x: number, nd: number = 1): number {
  // 반올림 규칙을 하나로: .5는 0에서 먼 쪽으로. (파이썬 round는 짝수 쪽 · JS Math.round는 위쪽이라 둘이 달라서 Python · TS 모두 이 함수를 쓴다)
  const f = 10 ** nd;
  return Math.sign(x) * (Math.floor(Math.abs(x) * f + 0.5) / f);
}

const same = (a: unknown, b: unknown): boolean => JSON.stringify(a) === JSON.stringify(b); // 값 전체가 같은지 (모양과 순서까지)
const clean = (s: string): string => s.replace(/[^0-9A-Za-z가-힣]/g, ""); // 글자 · 숫자만 남긴다(공백 · 문장 부호 제거)

const TRACKS: Record<string, string> = {"A": "외국어 회화 튜터", "B": "오디오북 생성기 확장", "C": "회의 통역기", "F": "자유 주제"};

type Seg = [string, string];
const CAST: Record<string, number> = {"해설": 7, "토끼": 2, "거북이": 5, "다람쥐": 0, "부엉이": 8}; // 등장인물 → 목소리 번호
const STORIES: Record<string, string> = {
  "저녁 숲": "숲속 마을에 저녁이 찾아왔습니다. 토끼가 하늘을 보며 말했습니다. \"벌써 해가 지네. 이제 집에 가야 해.\" 거북이가 천천히 고개를 들었습니다. \"서두르지 마. 천천히 가도 늦지 않아.\" 토끼는 발을 동동 굴렀습니다. \"너는 느려서 그렇지!\" 그러자 거북이가 웃으며 대답했습니다. \"느려도 길은 잃지 않아.\" 둘은 나란히 집으로 걸어갔습니다.",
  "한밤의 손님": "\"누구 없어요?\" 다람쥐가 문을 두드렸습니다. 한참 뒤에 부엉이가 창문을 열었습니다. \"이 밤중에 무슨 일이니?\" 다람쥐는 작은 자루를 내밀었습니다. \"도토리를 나눠 드리려고요.\"",
};
const STORY_TRUTH: Record<string, Seg[]> = {
  "저녁 숲": [["해설", "숲속 마을에 저녁이 찾아왔습니다. 토끼가 하늘을 보며 말했습니다."], ["토끼", "벌써 해가 지네. 이제 집에 가야 해."], ["해설", "거북이가 천천히 고개를 들었습니다."], ["거북이", "서두르지 마. 천천히 가도 늦지 않아."], ["해설", "토끼는 발을 동동 굴렀습니다."], ["토끼", "너는 느려서 그렇지!"], ["해설", "그러자 거북이가 웃으며 대답했습니다."], ["거북이", "느려도 길은 잃지 않아."], ["해설", "둘은 나란히 집으로 걸어갔습니다."]],
  "한밤의 손님": [["다람쥐", "누구 없어요?"], ["해설", "다람쥐가 문을 두드렸습니다. 한참 뒤에 부엉이가 창문을 열었습니다."], ["부엉이", "이 밤중에 무슨 일이니?"], ["해설", "다람쥐는 작은 자루를 내밀었습니다."], ["다람쥐", "도토리를 나눠 드리려고요."]],
}; // 정답: (읽는 사람, 글) 조각

function seedSplit(text: string, _cast: string[]): Seg[] {
  // 씨앗: 글 전체를 해설자 한 사람이 읽는다
  return [["해설", text.replaceAll('"', "")]];
}

function splitScript(text: string, cast: string[]): Seg[] {
  // 내가 쓰는 함수: 따옴표 밖은 해설, 안은 앞의 해설에 이름이 나온 등장인물이 읽는다
  const parts = text.split(/"([^"]*)"/); // [밖, 안, 밖, 안, …]
  const out: Seg[] = [];
  let speaker = "해설";
  parts.forEach((raw, i) => {
    const p = raw.trim();
    if (!p) return;
    if (i % 2 === 0) {
      out.push(["해설", p]);
      for (const name of cast) if (name !== "해설" && p.includes(name)) speaker = name;
    } else {
      out.push([speaker, p]);
    }
  });
  return out;
}

type BookRow = { story: string; text: string; want: string; got: string; ok: boolean };
function bookEval(fn: (text: string, cast: string[]) => Seg[]): { rows: BookRow[]; passed: number; score: number } {
  // 오디오북 평가: 두 이야기의 조각 14개를 (읽는 사람, 글)까지 정확히 나눴는가
  const rows: BookRow[] = [];
  for (const [title, text] of Object.entries(STORIES)) {
    let got: Seg[];
    try {
      got = fn(text, Object.keys(CAST)).map(([a, b]): Seg => [String(a), String(b).trim()]);
    } catch (e) {
      got = [["오류", (e as Error).name]];
    }
    for (const [sp, tx] of STORY_TRUTH[title]) {
      const mine = got.find(([, b]) => b === tx)?.[0] ?? null;
      rows.push({ story: title, text: tx, want: sp, got: mine || "(조각 없음)", ok: mine === sp });
    }
  }
  const p = rows.filter((r) => r.ok).length;
  return { rows, passed: p, score: roundHalfUp((100 * p) / rows.length) };
}

const seed = bookEval(seedSplit);
const mine = bookEval(splitScript);
console.log(`씨앗 ${seed.passed} / ${seed.rows.length} → ${seed.score.toFixed(1)}점 · 내 함수 ${mine.passed} / ${mine.rows.length} → ${mine.score.toFixed(1)}점`);
for (const [who, line] of splitScript(STORIES["한밤의 손님"], Object.keys(CAST))) console.log(`   [${who}] ${line}`);
const wrong = mine.rows.filter((r) => !r.ok);
for (const r of wrong) console.log(`   아직 틀림: ${r.text} → 읽는 사람 ${r.got} (정답 ${r.want})`);

const cast = ["해설", "토끼", "거북이"];
const cases: [string, Seg[]][] = [
  ['토끼가 말했습니다. "가자." 거북이가 웃었습니다. "그래." 둘은 걸었습니다.', [["해설", "토끼가 말했습니다."], ["토끼", "가자."], ["해설", "거북이가 웃었습니다."], ["거북이", "그래."], ["해설", "둘은 걸었습니다."]]],
  ["바람이 불었습니다.", [["해설", "바람이 불었습니다."]]], // 따옴표가 없으면 해설 한 조각
  ['"어서 와." 토끼가 손을 흔들었습니다. "보고 싶었어."', [["해설", "어서 와."], ["해설", "토끼가 손을 흔들었습니다."], ["토끼", "보고 싶었어."]]], // 앞에 이름이 없으면 해설
];
const got = cases.map(([t]) => splitScript(t, cast));
const okCases = got.length === 3 && same(got, cases.map((c) => c[1]));

const ok =
  seed.passed === 0 && seed.score === 0 && STORY_TRUTH["저녁 숲"].length + STORY_TRUTH["한밤의 손님"].length === 14 &&
  mine.passed === 13 && mine.score === 92.9 && wrong.length === 1 && wrong[0].text === "누구 없어요?" && wrong[0].got === "해설" && wrong[0].want === "다람쥐";
check(ok && okCases, "씨앗은 14조각 가운데 0개, 내 함수는 13개(92.9점)여야 해요. 맨 앞 따옴표처럼 앞에 이름이 없는 대사는 해설로 읽혀 한 조각이 아직 틀립니다.");

interp.typescript:
// D51 · 통역기: 가까운 문장 — 단독 실행 완성 코드 (Node 26 · TypeScript)
// 설치 불필요 (Node 내장만)
// 실행: node --experimental-strip-types d51_interp.ts   (인터넷 · GPU · 마이크 불필요 · 받아쓰기 · 말하기 모델은 쓰지 않고, 받아쓴 글을 미리 적어 둔 값으로 흉내)
//   받아쓴 글과 문장집의 자모 거리가 문턱 안일 때만 통역한다 · 문턱을 바꿔 가며 잰다
function check(cond: boolean, hint: string = "정답을 다시 확인하세요."): void {
  // 정답 확인 도우미: 조건이 맞으면 정답, 아니면 힌트를 보여 준다
  console.log(cond ? "[정답] 정답입니다!" : `[다시] ${hint}`);
}

function roundHalfUp(x: number, nd: number = 1): number {
  // 반올림 규칙을 하나로: .5는 0에서 먼 쪽으로. (파이썬 round는 짝수 쪽 · JS Math.round는 위쪽이라 둘이 달라서 Python · TS 모두 이 함수를 쓴다)
  const f = 10 ** nd;
  return Math.sign(x) * (Math.floor(Math.abs(x) * f + 0.5) / f);
}

const same = (a: unknown, b: unknown): boolean => JSON.stringify(a) === JSON.stringify(b); // 값 전체가 같은지 (모양과 순서까지)
const clean = (s: string): string => s.replace(/[^0-9A-Za-z가-힣]/g, ""); // 글자 · 숫자만 남긴다(공백 · 문장 부호 제거)

const TRACKS: Record<string, string> = {"A": "외국어 회화 튜터", "B": "오디오북 생성기 확장", "C": "회의 통역기", "F": "자유 주제"};

const PHRASEBOOK: Record<string, string> = {
  "회의는 내일 오후 세 시에 시작합니다": "The meeting starts at 3 p.m. tomorrow.",
  "예산안은 금요일까지 보내 주세요": "Please send the budget plan by Friday.",
  "이번 분기 매출이 십 퍼센트 늘었습니다": "Sales grew ten percent this quarter.",
  "다음 안건으로 넘어가겠습니다": "Let's move on to the next item.",
  "출시 일정을 일주일 미루겠습니다": "We will delay the launch by one week.",
  "질문 있으신 분 계십니까": "Does anyone have a question?",
  "자료는 회의 후에 공유하겠습니다": "I will share the materials after the meeting.",
  "담당자를 정해야 합니다": "We need to assign an owner.",
  "오늘 회의는 여기서 마치겠습니다": "That's all for today's meeting.",
  "고객 불만이 지난달보다 줄었습니다": "Customer complaints decreased from last month.",
  "계약서는 법무팀이 검토 중입니다": "The legal team is reviewing the contract.",
  "잠시 쉬었다가 계속하겠습니다": "Let's take a short break and continue.",
};
type Meet = { id: string; said: string; heard: string; truth: string | null };
const MEET: Meet[] = [
  {"id": "C1", "said": "회의는 내일 오후 세 시에 시작합니다", "heard": "회이는 내일 오후 세 시에 시작합니다", "truth": "회의는 내일 오후 세 시에 시작합니다"},
  {"id": "C2", "said": "예산안은 금요일까지 보내 주세요", "heard": "예산아는 금요일까지 보내 주세요", "truth": "예산안은 금요일까지 보내 주세요"},
  {"id": "C3", "said": "이번 분기 매출이 십 퍼센트 늘었습니다", "heard": "이번 분기 매출이 신 퍼센트 늘었습니다", "truth": "이번 분기 매출이 십 퍼센트 늘었습니다"},
  {"id": "C4", "said": "출시 일정을 일주일 미루겠습니다", "heard": "출시 일점을 일주일 미루겠습니다", "truth": "출시 일정을 일주일 미루겠습니다"},
  {"id": "C5", "said": "고객 불만이 지난달보다 줄었습니다", "heard": "고객 불마이 지난달보다 줄었습니다", "truth": "고객 불만이 지난달보다 줄었습니다"},
  {"id": "C6", "said": "오늘 회의는 여기서 마치겠습니다", "heard": "오늘 회의는 여기서 마치겟습니다", "truth": "오늘 회의는 여기서 마치겠습니다"},
  {"id": "C7", "said": "점심은 구내식당에서 먹겠습니다", "heard": "점심은 구내식당에서 먹겠습니다", "truth": null},
  {"id": "C8", "said": "출시 일정을 일주일 당기겠습니다", "heard": "출시 일정을 일주일 당기겠습니다", "truth": null},
]; // 회의 발화 8개: 받아쓴 글(받아쓰기 모델 대신 미리 적어 둔 값) · 문장집의 정답(없으면 null)

function jamo(s: string): string[] {
  // 한글을 초성 · 중성 · 종성 조각으로 쪼갠다(한글이 아니면 그대로)
  const out: string[] = [];
  for (const ch of s) {
    const o = (ch.codePointAt(0) as number) - 0xac00;
    if (o >= 0 && o < 11172) out.push(`초${Math.floor(o / 588)}`, `중${Math.floor((o % 588) / 28)}`, `종${o % 28}`);
    else out.push(ch);
  }
  return out;
}

function editDistance(a: string[], b: string[]): number {
  // 두 리스트의 편집 거리(바꾸기 · 넣기 · 빼기 각 1)
  const d = Array.from({ length: b.length + 1 }, (_, i) => i);
  for (let i = 1; i <= a.length; i++) {
    let prev = d[0];
    d[0] = i;
    for (let j = 1; j <= b.length; j++) {
      const cur = d[j];
      d[j] = Math.min(d[j] + 1, d[j - 1] + 1, prev + (a[i - 1] !== b[j - 1] ? 1 : 0));
      prev = cur;
    }
  }
  return d[b.length];
}

function ratio(text: string, phrase: string): number {
  // 받아쓴 글과 문장이 얼마나 다른가: 자모 거리 ÷ 문장의 자모 수. 0이면 같고, 클수록 다르다
  const p = clean(phrase);
  return roundHalfUp(editDistance(jamo(clean(text)), jamo(p)) / Math.max(1, jamo(p).length), 3);
}

type Matcher = (text: string, phrases: string[], maxRatio: number) => string | null;

const seedMatch: Matcher = (text, phrases) => {
  // 씨앗: 받아쓴 글이 문장집의 문장과 글자까지 똑같을 때만 통역한다
  return phrases.find((p) => clean(p) === clean(text)) ?? null;
};

const closestPhrase: Matcher = (text, phrases, maxRatio) => {
  // 내가 쓰는 함수: 차이가 가장 작은 문장을 찾아, 그 차이가 maxRatio 이하이면 그 문장을, 아니면 null
  let best: string | null = null;
  let br = 9.9;
  for (const p of phrases) {
    const r = ratio(text, p);
    if (r < br) {
      best = p;
      br = r;
    }
  }
  return br <= maxRatio ? best : null;
};

type InterpRow = { id: string; got: string | null; ok: boolean; bad: boolean; gap: number };
function interpEval(fn: Matcher, items: Meet[], maxRatio: number): { rows: InterpRow[]; passed: number; wrong: number; score: number } {
  // 통역 평가: 회의 발화를 옳은 문장으로 통역했는가(문장집에 없는 말은 통역하지 않아야 정답)
  const rows: InterpRow[] = items.map((it) => {
    let got: string | null;
    try {
      got = fn(it.heard, Object.keys(PHRASEBOOK), maxRatio);
    } catch (e) {
      got = `오류: ${(e as Error).name}`;
    }
    const ok = got === it.truth;
    return { id: it.id, got, ok, bad: got !== null && !ok, gap: Math.min(...Object.keys(PHRASEBOOK).map((p) => ratio(it.heard, p))) };
  });
  const p = rows.filter((r) => r.ok).length;
  return { rows, passed: p, wrong: rows.filter((r) => r.bad).length, score: roundHalfUp((100 * p) / rows.length) };
}

const sweep: { max_ratio: number; passed: number; wrong: number; score: number }[] = [];
for (const mr of [0.0, 0.05, 0.1, 0.2, 0.3]) { // 문턱값을 바꿔 가며 잰다
  const r = interpEval(closestPhrase, MEET, mr);
  sweep.push({ max_ratio: mr, passed: r.passed, wrong: r.wrong, score: r.score });
  console.log(`max_ratio ${String(mr).padEnd(4)} → 통과 ${r.passed} / 8 · 잘못 통역 ${r.wrong} · ${r.score.toFixed(1)}점`);
}
const seed = interpEval(seedMatch, MEET, 0.0);
console.log(`씨앗 ${seed.passed} / 8 → ${seed.score.toFixed(1)}점`);
const res = interpEval(closestPhrase, MEET, 0.1);
for (const r of res.rows) console.log(`  ${r.id} 가장 가까운 문장과의 차이 ${r.gap} → ${(r.got !== null && PHRASEBOOK[r.got]) || "(통역하지 않음)"}`);

const p = ["다음 안건으로 넘어가겠습니다", "출시 일정을 일주일 미루겠습니다", "질문 있으신 분 계십니까"];
const cases: [[string, number], string | null][] = [
  [["다음안건으로넘어가겠습니다", 0.0], p[0]], [["출시일점을일주일미루겠습니다.", 0.1], p[1]], [["출시일점을일주일미루겠습니다.", 0.0], null],
  [["출시일정을일주일당기겠습니다", 0.1], null], [["출시일정을일주일당기겠습니다", 0.3], p[1]], [["점심은구내식당에서먹겠습니다", 0.3], null],
];
const got = cases.map(([[t, m]]) => closestPhrase(t, p, m));
const okCases = got.length === 6 && same(got, cases.map((c) => c[1]));

const passed = sweep.map((s) => s.passed);
const wrongs = sweep.map((s) => s.wrong);
const gaps: Record<string, number> = Object.fromEntries(res.rows.map((r) => [r.id, r.gap]));
const okSweep =
  sweep.length === 5 && same(passed, [2, 8, 8, 7, 7]) && same(wrongs, [0, 0, 0, 1, 1]) &&
  wrongs.every((a, i) => i === 0 || wrongs[i - 1] <= a) && // 문턱을 올리면 잘못 통역은 줄지 않는다
  gaps["C7"] > 0.3 && gaps["C8"] > 0.1 && gaps["C8"] < 0.2; // C7은 어느 문턱에서도 통역하지 않고, C8은 문턱이 0.2일 때부터 잘못 통역
const ok = okSweep && seed.passed === 2 && seed.score === 25 && res.score === 100.0 && res.wrong === 0;
check(ok && okCases, "문턱 0.0에서는 씨앗과 같은 25점, 0.05~0.1에서는 8개 모두 통과, 0.2부터는 문장집에 없는 말(C8)을 잘못 통역해야 해요.");

demo.python:
# D51 · 5분 데모의 순서표 — 단독 실행 완성 코드 (Python 3.11)
# pip install (설치 불필요 · 표준 라이브러리만)
# 실행: python d51_demo.py   (인터넷 · GPU · 마이크 불필요 · 받아쓰기 · 말하기 모델은 쓰지 않고, 받아쓴 글을 미리 적어 둔 값으로 흉내)
#   단계 시간을 더해 300초에 들어가는지 재고, 발표 순서와 팀 코드를 만든다
import base64, hashlib, json, math, re, zlib


def check(cond: bool, hint: str = "정답을 다시 확인하세요.") -> None:
    """정답 확인 도우미: 조건이 맞으면 정답, 아니면 힌트를 보여 준다."""
    print("[정답] 정답입니다!" if cond else f"[다시] {hint}")


def round_half_up(x, nd=1):
    """반올림 규칙을 하나로: .5는 0에서 먼 쪽으로. (파이썬 round는 짝수 쪽 · JS Math.round는 위쪽이라 둘이 달라서 Python · TS 모두 이 함수를 쓴다)"""
    f = 10 ** nd
    return math.copysign(math.floor(abs(x) * f + 0.5) / f, x)


def clean(s):
    """글자 · 숫자만 남긴다(공백 · 문장 부호 제거)."""
    return re.sub(r"[^0-9A-Za-z가-힣]", "", s)


TRACKS = {'A': '외국어 회화 튜터', 'B': '오디오북 생성기 확장', 'C': '회의 통역기', 'F': '자유 주제'}


RUN = [
    ('누구의 어떤 불편인가', 40),
    ('준비된 입력으로 시연', 70),
    ('새 입력으로 시연', 60),
    ('숫자: 씨앗 → 지금', 50),
    ('안 되는 것 · 다음에 할 것', 50),
]                                              # 데모 순서표: (단계, 초)


def run_time(steps, limit):
    """내가 쓰는 함수: (모두 더한 시간, 넘친 시간). 넘치지 않았으면 넘친 시간은 0."""
    total = sum(s for _, s in steps)
    return total, max(0, total - limit)


def demo_order(teams, seed="D51"):
    """발표 순서를 뽑는다(같은 팀 목록 · 같은 seed면 늘 같은 순서)."""
    return sorted(teams, key=lambda t: hashlib.sha1((seed + "|" + t).encode("utf-8")).hexdigest())


def pack(kind, body):
    """팀 코드 · 평가 코드: JSON → 압축 → 글자 한 줄."""
    return f"D51{kind}|" + base64.b64encode(zlib.compress(json.dumps(body, ensure_ascii=False).encode("utf-8"), 9)).decode()


def unpack(code):
    """코드 한 줄 → (종류, 내용). D51 코드가 아니면 오류."""
    code = code.strip()
    if code[:4] not in ("D51T", "D51B") or code[4:5] != "|":
        raise ValueError("D51 코드가 아닙니다")
    return code[3], json.loads(zlib.decompress(base64.b64decode(code[5:])).decode("utf-8"))


total, over = run_time(RUN, 300)
print(f"순서표 {total}초 / 300초 → {'들어갑니다 (남는 시간 ' + str(300 - total) + '초)' if over == 0 else str(over) + '초 넘칩니다. 단계를 하나 빼세요'}")
cases = [(([("문제", 40), ("시연", 150), ("숫자", 60), ("한계", 40)], 300), (290, 0)), (([("문제", 90), ("시연", 200), ("숫자", 60)], 300), (350, 50)), (([], 300), (0, 0))]
got = [run_time(*args) for args, _ in cases]
ok_time = len(got) == 3 and got == [w for _, w in cases] and (total, over) == (270, 0)

teams = ["우리 팀", "가상 팀 · 메아리", "가상 팀 · 책갈피", "가상 팀 · 다리"]
order = demo_order(teams)
print("발표 순서:", " → ".join(order))
ok_order = (order == ["가상 팀 · 책갈피", "가상 팀 · 메아리", "우리 팀", "가상 팀 · 다리"] and demo_order(list(reversed(teams))) == order and sorted(order) == sorted(teams)
            and demo_order(teams, "D52") != order)       # 같은 목록이면 늘 같은 순서 · seed가 다르면 다른 순서

info = {"team": "우리 팀", "track": "A", "title": "따라 말하기 튜터", "metric": "짚은 낱말 정확도", "base": 50.0, "mine": 100.0, "target": 85, "level": 2}
code = pack("T", info)
kind, back = unpack(code)
print("팀 코드:", code[:24] + "…", "→", kind, back["team"])
try:
    unpack("엉터리 코드")
    bad_code = False
except ValueError:
    bad_code = True
ok_code = code.startswith("D51T|") and kind == "T" and back == info and bad_code and unpack(pack("B", {"from": "우리 팀", "scores": {}}))[0] == "B"

check(ok_time and ok_order and ok_code, "순서표는 270초로 300초에 들어가고 넘치면 넘친 만큼 알려야 해요. 발표 순서는 같은 팀 목록이면 늘 같고, 팀 코드는 풀면 그대로 돌아와야 해요.")

demo.typescript:
// D51 · 5분 데모의 순서표 — 단독 실행 완성 코드 (Node 26 · TypeScript)
// 설치 불필요 (Node 내장만)
// 실행: node --experimental-strip-types d51_demo.ts   (인터넷 · GPU · 마이크 불필요 · 받아쓰기 · 말하기 모델은 쓰지 않고, 받아쓴 글을 미리 적어 둔 값으로 흉내)
//   단계 시간을 더해 300초에 들어가는지 재고, 발표 순서와 팀 코드를 만든다
import { createHash } from "node:crypto";
import { deflateSync, inflateSync } from "node:zlib";
function check(cond: boolean, hint: string = "정답을 다시 확인하세요."): void {
  // 정답 확인 도우미: 조건이 맞으면 정답, 아니면 힌트를 보여 준다
  console.log(cond ? "[정답] 정답입니다!" : `[다시] ${hint}`);
}

function roundHalfUp(x: number, nd: number = 1): number {
  // 반올림 규칙을 하나로: .5는 0에서 먼 쪽으로. (파이썬 round는 짝수 쪽 · JS Math.round는 위쪽이라 둘이 달라서 Python · TS 모두 이 함수를 쓴다)
  const f = 10 ** nd;
  return Math.sign(x) * (Math.floor(Math.abs(x) * f + 0.5) / f);
}

const same = (a: unknown, b: unknown): boolean => JSON.stringify(a) === JSON.stringify(b); // 값 전체가 같은지 (모양과 순서까지)
const clean = (s: string): string => s.replace(/[^0-9A-Za-z가-힣]/g, ""); // 글자 · 숫자만 남긴다(공백 · 문장 부호 제거)

const TRACKS: Record<string, string> = {"A": "외국어 회화 튜터", "B": "오디오북 생성기 확장", "C": "회의 통역기", "F": "자유 주제"};

const RUN: [string, number][] = [
  ["누구의 어떤 불편인가", 40],
  ["준비된 입력으로 시연", 70],
  ["새 입력으로 시연", 60],
  ["숫자: 씨앗 → 지금", 50],
  ["안 되는 것 · 다음에 할 것", 50],
]; // 데모 순서표: (단계, 초)

function runTime(steps: [string, number][], limit: number): [number, number] {
  // 내가 쓰는 함수: (모두 더한 시간, 넘친 시간). 넘치지 않았으면 넘친 시간은 0
  const total = steps.reduce((a, [, s]) => a + s, 0);
  return [total, Math.max(0, total - limit)];
}

function demoOrder(teams: string[], seed: string = "D51"): string[] {
  // 발표 순서를 뽑는다(같은 팀 목록 · 같은 seed면 늘 같은 순서)
  const key = (t: string): string => createHash("sha1").update(seed + "|" + t, "utf8").digest("hex");
  return [...teams].sort((a, b) => (key(a) < key(b) ? -1 : key(a) > key(b) ? 1 : 0));
}

function pack(kind: string, body: unknown): string {
  // 팀 코드 · 평가 코드: JSON → 압축 → 글자 한 줄
  return `D51${kind}|` + deflateSync(Buffer.from(JSON.stringify(body), "utf8"), { level: 9 }).toString("base64");
}

function unpack(code: string): [string, any] {
  // 코드 한 줄 → (종류, 내용). D51 코드가 아니면 오류
  const c = code.trim();
  if (!["D51T", "D51B"].includes(c.slice(0, 4)) || c.slice(4, 5) !== "|") throw new Error("D51 코드가 아닙니다");
  return [c[3], JSON.parse(inflateSync(Buffer.from(c.slice(5), "base64")).toString("utf8"))];
}

const [total, over] = runTime(RUN, 300);
console.log(`순서표 ${total}초 / 300초 → ${over === 0 ? `들어갑니다 (남는 시간 ${300 - total}초)` : `${over}초 넘칩니다. 단계를 하나 빼세요`}`);
const cases: [[[string, number][], number], [number, number]][] = [
  [[[["문제", 40], ["시연", 150], ["숫자", 60], ["한계", 40]], 300], [290, 0]],
  [[[["문제", 90], ["시연", 200], ["숫자", 60]], 300], [350, 50]],
  [[[], 300], [0, 0]],
];
const got = cases.map(([[steps, limit]]) => runTime(steps, limit));
const okTime = got.length === 3 && same(got, cases.map((c) => c[1])) && total === 270 && over === 0;

const teams = ["우리 팀", "가상 팀 · 메아리", "가상 팀 · 책갈피", "가상 팀 · 다리"];
const order = demoOrder(teams);
console.log("발표 순서:", order.join(" → "));
const okOrder =
  same(order, ["가상 팀 · 책갈피", "가상 팀 · 메아리", "우리 팀", "가상 팀 · 다리"]) && same(demoOrder([...teams].reverse()), order) && same([...order].sort(), [...teams].sort()) &&
  !same(demoOrder(teams, "D52"), order); // 같은 목록이면 늘 같은 순서 · seed가 다르면 다른 순서

const info = { team: "우리 팀", track: "A", title: "따라 말하기 튜터", metric: "짚은 낱말 정확도", base: 50.0, mine: 100.0, target: 85, level: 2 };
const code = pack("T", info);
const [kind, back] = unpack(code);
console.log("팀 코드:", code.slice(0, 24) + "…", "→", kind, back.team);
let badCode = false;
try {
  unpack("엉터리 코드");
} catch {
  badCode = true;
}
const okCode = code.startsWith("D51T|") && kind === "T" && same(back, info) && badCode && unpack(pack("B", { from: "우리 팀", scores: {} }))[0] === "B";

check(okTime && okOrder && okCode, "순서표는 270초로 300초에 들어가고 넘치면 넘친 만큼 알려야 해요. 발표 순서는 같은 팀 목록이면 늘 같고, 팀 코드는 풀면 그대로 돌아와야 해요.");

peer.python:
# D51 · 동료 평가와 집계 — 단독 실행 완성 코드 (Python 3.11)
# pip install (설치 불필요 · 표준 라이브러리만)
# 실행: python d51_peer.py   (인터넷 · GPU · 마이크 불필요 · 받아쓰기 · 말하기 모델은 쓰지 않고, 받아쓴 글을 미리 적어 둔 값으로 흉내)
#   기준별 평균 · 자기 표 빼기 · 데모데이 점수 = 평가 70 + 측정 30으로 팀 순위를 낸다
import math, re


def check(cond: bool, hint: str = "정답을 다시 확인하세요.") -> None:
    """정답 확인 도우미: 조건이 맞으면 정답, 아니면 힌트를 보여 준다."""
    print("[정답] 정답입니다!" if cond else f"[다시] {hint}")


def round_half_up(x, nd=1):
    """반올림 규칙을 하나로: .5는 0에서 먼 쪽으로. (파이썬 round는 짝수 쪽 · JS Math.round는 위쪽이라 둘이 달라서 Python · TS 모두 이 함수를 쓴다)"""
    f = 10 ** nd
    return math.copysign(math.floor(abs(x) * f + 0.5) / f, x)


def clean(s):
    """글자 · 숫자만 남긴다(공백 · 문장 부호 제거)."""
    return re.sub(r"[^0-9A-Za-z가-힣]", "", s)


TRACKS = {'A': '외국어 회화 튜터', 'B': '오디오북 생성기 확장', 'C': '회의 통역기', 'F': '자유 주제'}


DEMO_TEAMS = {
    '가상 팀 · 메아리': {'team': '가상 팀 · 메아리', 'track': 'A', 'title': '따라 말하기 튜터', 'base': 50.0, 'mine': 100.0, 'target': 85, 'level': 2},
    '가상 팀 · 책갈피': {'team': '가상 팀 · 책갈피', 'track': 'B', 'title': '목소리 셋의 동화책', 'base': 0.0, 'mine': 92.9, 'target': 95, 'level': 1},
    '가상 팀 · 다리': {'team': '가상 팀 · 다리', 'track': 'C', 'title': '회의 한 줄 통역', 'base': None, 'mine': None, 'target': None, 'level': 0},
}                                # 가상 팀 셋(집계를 미리 보려는 것 · 점수는 지어낸 것)
DEMO_BALLOTS = [
    {'from': '가상 팀 · 메아리', 'scores': {'가상 팀 · 책갈피': [4, 4, 3, 5, 4], '가상 팀 · 다리': [3, 4, 1, 4, 2]}},
    {'from': '가상 팀 · 책갈피', 'scores': {'가상 팀 · 메아리': [5, 4, 5, 4, 4], '가상 팀 · 다리': [4, 3, 2, 5, 2]}},
    {'from': '가상 팀 · 다리', 'scores': {'가상 팀 · 메아리': [4, 5, 5, 3, 5], '가상 팀 · 책갈피': [4, 5, 4, 4, 5], '가상 팀 · 다리': [5, 5, 5, 5, 5]}},
]


def peer_mean(ballots, team):
    """내가 쓰는 함수: team이 받은 점수를 기준별로 평균(소수 둘째 자리). 자기 표는 빼고, 표가 하나도 없으면 None."""
    rows = [b["scores"][team] for b in ballots if b["from"] != team and team in b["scores"]]
    if not rows:
        return None
    return [round_half_up(sum(r[i] for r in rows) / len(rows), 2) for i in range(len(rows[0]))]


def demo_score(peer, measured):
    """데모데이 점수 = 70 × (다섯 평균의 평균 ÷ 5) + 15 × measured. 소수 첫째 자리."""
    return round_half_up(0.7 * (sum(peer) / len(peer)) / 5 * 100 + 15 * measured, 1)


def level_of(mine, target):
    """측정 단계: 0 숫자 없음 · 1 쟀음 · 2 목표에 닿음."""
    if mine is None:
        return 0
    return 2 if isinstance(target, (int, float)) and mine >= target else 1


def clean_ballot(ballot, teams):
    """평가표 점검: 발표 순서표에 없는 팀 · 1~5의 정수 다섯 개가 아닌 점수는 뺀다."""
    out = {}
    for team, s in ballot.items():
        if team not in teams:
            continue
        if not (isinstance(s, (list, tuple)) and len(s) == 5 and all(type(v) is int and 1 <= v <= 5 for v in s)):
            continue
        out[team] = list(s)
    return out


def tally(ballots, teams):
    """집계: 팀마다 기준별 평균 · 받은 표 · 점수를 내고 점수 높은 순으로(표가 없는 팀은 맨 뒤)."""
    rows = []
    for name, info in teams.items():
        p = peer_mean(ballots, name)
        votes = sum(1 for b in ballots if b["from"] != name and name in b["scores"])
        rows.append({"team": name, "peer": p, "votes": votes, "level": info["level"], "score": None if p is None else demo_score(p, info["level"])})
    return sorted(rows, key=lambda r: (r["score"] is None, -(r["score"] or 0)))


b = [{"from": "가", "scores": {"나": [4, 4, 3, 5, 4], "다": [3, 4, 1, 4, 2]}}, {"from": "나", "scores": {"가": [5, 4, 5, 4, 4], "다": [4, 3, 2, 5, 2]}},
     {"from": "다", "scores": {"가": [4, 5, 5, 3, 5], "나": [4, 5, 4, 4, 5], "다": [5, 5, 5, 5, 5]}}]
got = [peer_mean(b, t) for t in ["가", "다", "나", "라"]]
print("기준별 평균:", got)
ok_mean = len(got) == 4 and got == [[4.5, 4.5, 5.0, 3.5, 4.5], [3.5, 3.5, 1.5, 4.5, 2.0], [4.0, 4.5, 3.5, 4.5, 4.5], None]   # 다 팀의 자기 표(5점)는 빠지고, 표가 없는 팀은 None

scores = [demo_score(p, m) for p, m in [([5, 5, 5, 5, 5], 2), ([4.5, 4.5, 5.0, 3.5, 4.5], 2), ([3.5, 3.5, 1.5, 4.5, 2.0], 0), ([4.0, 4.5, 3.5, 4.5, 4.5], 1)]]
print("데모데이 점수:", scores)
ok_score = len(scores) == 4 and scores == [100.0, 91.6, 42.0, 73.8]

rows = tally(DEMO_BALLOTS, DEMO_TEAMS)
for i, r in enumerate(rows, 1):
    print(f"{i}위 {r['team']} · 받은 표 {r['votes']} · 평균 {r['peer']} · 측정 {r['level']} → {r['score']}점")
ok_tally = ([r["team"] for r in rows] == ["가상 팀 · 메아리", "가상 팀 · 책갈피", "가상 팀 · 다리"] and [r["score"] for r in rows] == [91.6, 73.8, 42.0]
            and [r["votes"] for r in rows] == [2, 2, 2])
with_nobody = tally(DEMO_BALLOTS, {**DEMO_TEAMS, "우리 팀": {"level": 1}})          # 아무도 점수를 주지 않은 팀은 표 0 · 점수 None으로 맨 뒤
ok_none = with_nobody[-1]["team"] == "우리 팀" and with_nobody[-1]["score"] is None and with_nobody[-1]["votes"] == 0 and len(with_nobody) == 4

mine = {"가상 팀 · 메아리": [4, 4, 4, 4, 4], "가상 팀 · 책갈피": [3, 3, 3, 3, 6], "가상 팀 · 다리": [True] * 5, "엉뚱한 팀": [3, 3, 3, 3, 3]}
ok_clean = clean_ballot(mine, DEMO_TEAMS) == {"가상 팀 · 메아리": [4, 4, 4, 4, 4]}      # 6점 · True(불리언) 다섯 개 · 없는 팀은 빠진다
print("평가표 점검: 남은 팀", list(clean_ballot(mine, DEMO_TEAMS)))
ok_level = [level_of(None, None), level_of(70.0, 85), level_of(92.9, 85), level_of(50.0, None)] == [0, 1, 2, 1]

check(ok_mean and ok_score and ok_tally and ok_none and ok_clean and ok_level, "자기 팀이 준 표는 빼고 평균을 내고, 점수 = 70 × (평균 ÷ 5) + 15 × 측정 단계여야 해요. 표가 없는 팀은 점수 없음으로 맨 뒤에 둡니다.")

