];
const got = ["가", "다", "나", "라"].map((t) => peerMean(b, t));
console.log("기준별 평균:", JSON.stringify(got));
const okMean = got.length === 4 && same(got, [[4.5, 4.5, 5.0, 3.5, 4.5], [3.5, 3.5, 1.5, 4.5, 2.0], [4.0, 4.5, 3.5, 4.5, 4.5], null]); // 다 팀의 자기 표(5점)는 빠지고, 표가 없는 팀은 null

const scores = ([[[5, 5, 5, 5, 5], 2], [[4.5, 4.5, 5.0, 3.5, 4.5], 2], [[3.5, 3.5, 1.5, 4.5, 2.0], 0], [[4.0, 4.5, 3.5, 4.5, 4.5], 1]] as [number[], number][]).map(([p, m]) => demoScore(p, m));
console.log("데모데이 점수:", JSON.stringify(scores));
const okScore = scores.length === 4 && same(scores, [100.0, 91.6, 42.0, 73.8]);

const rows = tally(DEMO_BALLOTS, DEMO_TEAMS);
rows.forEach((r, i) => console.log(`${i + 1}위 ${r.team} · 받은 표 ${r.votes} · 평균 ${JSON.stringify(r.peer)} · 측정 ${r.level} → ${r.score}점`));
const okTally =
  same(rows.map((r) => r.team), ["가상 팀 · 메아리", "가상 팀 · 책갈피", "가상 팀 · 다리"]) && same(rows.map((r) => r.score), [91.6, 73.8, 42.0]) &&
  same(rows.map((r) => r.votes), [2, 2, 2]);
const withNobody = tally(DEMO_BALLOTS, { ...DEMO_TEAMS, "우리 팀": { level: 1 } }); // 아무도 점수를 주지 않은 팀은 표 0 · 점수 null로 맨 뒤
const last = withNobody[withNobody.length - 1];
const okNone = last.team === "우리 팀" && last.score === null && last.votes === 0 && withNobody.length === 4;

const mine = { "가상 팀 · 메아리": [4, 4, 4, 4, 4], "가상 팀 · 책갈피": [3, 3, 3, 3, 6], "가상 팀 · 다리": [true, true, true, true, true], "엉뚱한 팀": [3, 3, 3, 3, 3] };
const okClean = same(cleanBallot(mine, DEMO_TEAMS), { "가상 팀 · 메아리": [4, 4, 4, 4, 4] }); // 6점 · true(불리언) 다섯 개 · 없는 팀은 빠진다
console.log("평가표 점검: 남은 팀", Object.keys(cleanBallot(mine, DEMO_TEAMS)));
const okLevel = same([levelOf(null, null), levelOf(70.0, 85), levelOf(92.9, 85), levelOf(50.0, null)], [0, 1, 2, 1]);

check(okMean && okScore && okTally && okNone && okClean && okLevel, "자기 팀이 준 표는 빼고 평균을 내고, 점수 = 70 × (평균 ÷ 5) + 15 × 측정 단계여야 해요. 표가 없는 팀은 점수 없음으로 맨 뒤에 둡니다.");

