def pick_scope(features, minutes):
    """내가 쓰는 함수: must는 모두 넣고, 나머지는 가치 높은 순(같으면 짧은 순)으로 남은 시간에 들어가는 것만 넣는다."""
    out, left = [], minutes
    for f in features:
        if f["must"]:
            out.append(f["name"])
            left -= f["min"]
    for f in sorted([f for f in features if not f["must"]], key=lambda f: (-f["value"], f["min"])):
        if f["min"] <= left:
            out.append(f["name"])
            left -= f["min"]
    return out


def check_plan(plan):
    """기획서에서 빠졌거나 모호한 곳을 찾는다. → 고칠 곳의 리스트(비어 있으면 통과)"""
    bad = []
    if not plan.get("team") or plan["team"] == "우리 팀":
        bad.append("team: 팀 이름을 정하세요")
    if plan.get("track") not in TRACKS:
        bad.append("track: A · B · C · F 가운데 하나")
    user = str(plan.get("user") or "")
    if len(user) < 4 or "모든" in user or "누구나" in user:
        bad.append("user: 누가 쓰나요? '모든 사람'이 아니라 한 사람을 떠올릴 수 있게")
    if len(str(plan.get("problem") or "")) < 12:
        bad.append("problem: 그 사람이 지금 무엇이 불편한가요? 한 문장으로(12자 이상)")
    f = plan.get("features") or []
    if not (len(f) >= 3 and all({"name", "min", "must", "value"} <= set(x) for x in f)):
        bad.append("features: 기능 3개 이상, 기능마다 name · min · must · value")
    elif not any(x["must"] for x in f):
        bad.append("features: 꼭 있어야 하는 기능(must=True)이 하나는 있어야 합니다")
    m = plan.get("metric") or {}
    if not (len(str(m.get("name") or "")) >= 4 and isinstance(m.get("target"), (int, float))):
        bad.append("metric: '됐다'를 보여 줄 숫자의 이름(name)과 목표값(target)")
