def run_time(steps, limit):
    """내가 쓰는 함수: (모두 더한 시간, 넘친 시간). 넘치지 않았으면 넘친 시간은 0."""
    total = sum(s for _, s in steps)
    return total, max(0, total - limit)


def demo_order(teams, seed="D51"):
    """발표 순서를 뽑는다(같은 팀 목록 · 같은 seed면 늘 같은 순서)."""
    return sorted(teams, key=lambda t: hashlib.sha1((seed + "|" + t).encode("utf-8")).hexdigest())


def pack(kind, body):
    """팀 코드 · 평가 코드: JSON → 압축 → 글자 한 줄."""
    return f"D51{kind}|" + base64.b64encode(zlib.compress(json.dumps(body, ensure_ascii=False).encode("utf-8"), 9)).decode()


def unpack(code):
    """코드 한 줄 → (종류, 내용). D51 코드가 아니면 오류."""
    code = code.strip()
    if code[:4] not in ("D51T", "D51B") or code[4:5] != "|":
        raise ValueError("D51 코드가 아닙니다")
    return code[3], json.loads(zlib.decompress(base64.b64decode(code[5:])).decode("utf-8"))


