def peer_mean(ballots, team):
    """내가 쓰는 함수: team이 받은 점수를 기준별로 평균(소수 둘째 자리). 자기 표는 빼고, 표가 하나도 없으면 None."""
    rows = [b["scores"][team] for b in ballots if b["from"] != team and team in b["scores"]]
    if not rows:
        return None
    return [round_half_up(sum(r[i] for r in rows) / len(rows), 2) for i in range(len(rows[0]))]


def demo_score(peer, measured):
    """데모데이 점수 = 70 × (다섯 평균의 평균 ÷ 5) + 15 × measured. 소수 첫째 자리."""
    return round_half_up(0.7 * (sum(peer) / len(peer)) / 5 * 100 + 15 * measured, 1)


def level_of(mine, target):
    """측정 단계: 0 숫자 없음 · 1 쟀음 · 2 목표에 닿음."""
    if mine is None:
        return 0
    return 2 if isinstance(target, (int, float)) and mine >= target else 1


def clean_ballot(ballot, teams):
    """평가표 점검: 발표 순서표에 없는 팀 · 1~5의 정수 다섯 개가 아닌 점수는 뺀다."""
    out = {}
    for team, s in ballot.items():
        if team not in teams:
            continue
        if not (isinstance(s, (list, tuple)) and len(s) == 5 and all(type(v) is int and 1 <= v <= 5 for v in s)):
            continue
        out[team] = list(s)
    return out


def tally(ballots, teams):
    """집계: 팀마다 기준별 평균 · 받은 표 · 점수를 내고 점수 높은 순으로(표가 없는 팀은 맨 뒤)."""
    rows = []
    for name, info in teams.items():
        p = peer_mean(ballots, name)
        votes = sum(1 for b in ballots if b["from"] != name and name in b["scores"])
        rows.append({"team": name, "peer": p, "votes": votes, "level": info["level"], "score": None if p is None else demo_score(p, info["level"])})
    return sorted(rows, key=lambda r: (r["score"] is None, -(r["score"] or 0)))


