}; // 정답: (읽는 사람, 글) 조각

function seedSplit(text: string, _cast: string[]): Seg[] {
  // 씨앗: 글 전체를 해설자 한 사람이 읽는다
  return [["해설", text.replaceAll('"', "")]];
}

function splitScript(text: string, cast: string[]): Seg[] {
  // 내가 쓰는 함수: 따옴표 밖은 해설, 안은 앞의 해설에 이름이 나온 등장인물이 읽는다
  const parts = text.split(/"([^"]*)"/); // [밖, 안, 밖, 안, …]
  const out: Seg[] = [];
  let speaker = "해설";
  parts.forEach((raw, i) => {
    const p = raw.trim();
    if (!p) return;
    if (i % 2 === 0) {
      out.push(["해설", p]);
      for (const name of cast) if (name !== "해설" && p.includes(name)) speaker = name;
    } else {
      out.push([speaker, p]);
    }
  });
  return out;
}

type BookRow = { story: string; text: string; want: string; got: string; ok: boolean };
function bookEval(fn: (text: string, cast: string[]) => Seg[]): { rows: BookRow[]; passed: number; score: number } {
  // 오디오북 평가: 두 이야기의 조각 14개를 (읽는 사람, 글)까지 정확히 나눴는가
  const rows: BookRow[] = [];
  for (const [title, text] of Object.entries(STORIES)) {
    let got: Seg[];
    try {
      got = fn(text, Object.keys(CAST)).map(([a, b]): Seg => [String(a), String(b).trim()]);
    } catch (e) {
      got = [["오류", (e as Error).name]];
    }
    for (const [sp, tx] of STORY_TRUTH[title]) {
      const mine = got.find(([, b]) => b === tx)?.[0] ?? null;
      rows.push({ story: title, text: tx, want: sp, got: mine || "(조각 없음)", ok: mine === sp });
    }
  }
  const p = rows.filter((r) => r.ok).length;
  return { rows, passed: p, score: roundHalfUp((100 * p) / rows.length) };
}

