function jamo(s: string): string[] {
  // 한글을 초성 · 중성 · 종성 조각으로 쪼갠다(한글이 아니면 그대로)
  const out: string[] = [];
  for (const ch of s) {
    const o = (ch.codePointAt(0) as number) - 0xac00;
    if (o >= 0 && o < 11172) out.push(`초${Math.floor(o / 588)}`, `중${Math.floor((o % 588) / 28)}`, `종${o % 28}`);
    else out.push(ch);
  }
  return out;
}

function editDistance(a: string[], b: string[]): number {
  // 두 리스트의 편집 거리(바꾸기 · 넣기 · 빼기 각 1)
  const d = Array.from({ length: b.length + 1 }, (_, i) => i);
  for (let i = 1; i <= a.length; i++) {
    let prev = d[0];
    d[0] = i;
    for (let j = 1; j <= b.length; j++) {
      const cur = d[j];
      d[j] = Math.min(d[j] + 1, d[j - 1] + 1, prev + (a[i - 1] !== b[j - 1] ? 1 : 0));
      prev = cur;
    }
  }
  return d[b.length];
}

function ratio(text: string, phrase: string): number {
  // 받아쓴 글과 문장이 얼마나 다른가: 자모 거리 ÷ 문장의 자모 수. 0이면 같고, 클수록 다르다
  const p = clean(phrase);
  return roundHalfUp(editDistance(jamo(clean(text)), jamo(p)) / Math.max(1, jamo(p).length), 3);
}

type Matcher = (text: string, phrases: string[], maxRatio: number) => string | null;

const seedMatch: Matcher = (text, phrases) => {
  // 씨앗: 받아쓴 글이 문장집의 문장과 글자까지 똑같을 때만 통역한다
  return phrases.find((p) => clean(p) === clean(text)) ?? null;
};

const closestPhrase: Matcher = (text, phrases, maxRatio) => {
  // 내가 쓰는 함수: 차이가 가장 작은 문장을 찾아, 그 차이가 maxRatio 이하이면 그 문장을, 아니면 null
  let best: string | null = null;
  let br = 9.9;
  for (const p of phrases) {
    const r = ratio(text, p);
    if (r < br) {
      best = p;
      br = r;
    }
  }
  return br <= maxRatio ? best : null;
};

type InterpRow = { id: string; got: string | null; ok: boolean; bad: boolean; gap: number };
function interpEval(fn: Matcher, items: Meet[], maxRatio: number): { rows: InterpRow[]; passed: number; wrong: number; score: number } {
  // 통역 평가: 회의 발화를 옳은 문장으로 통역했는가(문장집에 없는 말은 통역하지 않아야 정답)
  const rows: InterpRow[] = items.map((it) => {
    let got: string | null;
    try {
      got = fn(it.heard, Object.keys(PHRASEBOOK), maxRatio);
    } catch (e) {
      got = `오류: ${(e as Error).name}`;
    }
    const ok = got === it.truth;
    return { id: it.id, got, ok, bad: got !== null && !ok, gap: Math.min(...Object.keys(PHRASEBOOK).map((p) => ratio(it.heard, p))) };
  });
  const p = rows.filter((r) => r.ok).length;
  return { rows, passed: p, wrong: rows.filter((r) => r.bad).length, score: roundHalfUp((100 * p) / rows.length) };
}

