function pickScope(features: Feature[], minutes: number): string[] {
  // 내가 쓰는 함수: must는 모두 넣고, 나머지는 가치 높은 순(같으면 짧은 순)으로 남은 시간에 들어가는 것만 넣는다
  const out: string[] = [];
  let left = minutes;
  for (const f of features) {
    if (f.must) {
      out.push(f.name);
      left -= f.min;
    }
  }
  for (const f of features.filter((x) => !x.must).sort((a, b) => b.value - a.value || a.min - b.min)) {
    if (f.min <= left) {
      out.push(f.name);
      left -= f.min;
    }
  }
  return out;
}

function checkPlan(plan: Record<string, any>): string[] {
  // 기획서에서 빠졌거나 모호한 곳을 찾는다. → 고칠 곳의 리스트(비어 있으면 통과)
  const bad: string[] = [];
  if (!plan.team || plan.team === "우리 팀") bad.push("team: 팀 이름을 정하세요");
  if (!Object.hasOwn(TRACKS, plan.track)) bad.push("track: A · B · C · F 가운데 하나");
  const user = String(plan.user || "");
  if (user.length < 4 || user.includes("모든") || user.includes("누구나")) bad.push("user: 누가 쓰나요? '모든 사람'이 아니라 한 사람을 떠올릴 수 있게");
  if (String(plan.problem || "").length < 12) bad.push("problem: 그 사람이 지금 무엇이 불편한가요? 한 문장으로(12자 이상)");
  const f: Feature[] = plan.features || [];
  if (!(f.length >= 3 && f.every((x) => ["name", "min", "must", "value"].every((k) => k in x)))) bad.push("features: 기능 3개 이상, 기능마다 name · min · must · value");
  else if (!f.some((x) => x.must)) bad.push("features: 꼭 있어야 하는 기능(must=True)이 하나는 있어야 합니다");
  const m = plan.metric || {};
  if (!(String(m.name || "").length >= 4 && typeof m.target === "number")) bad.push("metric: '됐다'를 보여 줄 숫자의 이름(name)과 목표값(target)");
  return bad;
}

