function runTime(steps: [string, number][], limit: number): [number, number] {
  // 내가 쓰는 함수: (모두 더한 시간, 넘친 시간). 넘치지 않았으면 넘친 시간은 0
  const total = steps.reduce((a, [, s]) => a + s, 0);
  return [total, Math.max(0, total - limit)];
}

function demoOrder(teams: string[], seed: string = "D51"): string[] {
  // 발표 순서를 뽑는다(같은 팀 목록 · 같은 seed면 늘 같은 순서)
  const key = (t: string): string => createHash("sha1").update(seed + "|" + t, "utf8").digest("hex");
  return [...teams].sort((a, b) => (key(a) < key(b) ? -1 : key(a) > key(b) ? 1 : 0));
}

function pack(kind: string, body: unknown): string {
  // 팀 코드 · 평가 코드: JSON → 압축 → 글자 한 줄
  return `D51${kind}|` + deflateSync(Buffer.from(JSON.stringify(body), "utf8"), { level: 9 }).toString("base64");
}

function unpack(code: string): [string, any] {
  // 코드 한 줄 → (종류, 내용). D51 코드가 아니면 오류
  const c = code.trim();
  if (!["D51T", "D51B"].includes(c.slice(0, 4)) || c.slice(4, 5) !== "|") throw new Error("D51 코드가 아닙니다");
  return [c[3], JSON.parse(inflateSync(Buffer.from(c.slice(5), "base64")).toString("utf8"))];
}

